import type {
  AccessScope,
  AgentBackend,
  ContextSnapshot,
  CronJob,
  DirectoryBinding,
  ListResponse,
  McpBinding,
  McpServerConfig,
  Message,
  Project,
  ProjectArtifact,
  Secret,
  Task,
  TaskRunAttempt,
  ToolBinding,
} from "../types";

// Prefer a runtime-injected value (see public/runtime-config.js, generated by
// the Docker entrypoint from the VITE_API_URL container env var at startup)
// so the same build can point at different backends without rebuilding.
// Falls back to the build-time Vite env var, then localhost.
const BASE_URL =
  (typeof window !== "undefined" && window.__MUSTER_API_URL__) ||
  import.meta.env.VITE_API_URL ||
  "http://localhost:8080";

class ApiError extends Error {
  status: number;
  body: unknown;
  constructor(status: number, body: unknown) {
    super(`API error ${status}: ${JSON.stringify(body)}`);
    this.status = status;
    this.body = body;
  }
}

async function request<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const res = await fetch(`${BASE_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(options.headers ?? {}),
    },
  });
  if (!res.ok) {
    let body: unknown = null;
    try {
      body = await res.json();
    } catch {
      // ignore body parse errors
    }
    throw new ApiError(res.status, body);
  }
  if (res.status === 204) {
    return undefined as T;
  }
  return (await res.json()) as T;
}

const get = <T>(path: string) => request<T>(path, { method: "GET" });
const post = <T>(path: string, body?: unknown) =>
  request<T>(path, { method: "POST", body: body ? JSON.stringify(body) : undefined });
const patch = <T>(path: string, body?: unknown) =>
  request<T>(path, { method: "PATCH", body: body ? JSON.stringify(body) : undefined });
const put = <T>(path: string, body?: unknown) =>
  request<T>(path, { method: "PUT", body: body ? JSON.stringify(body) : undefined });
const del = <T>(path: string) => request<T>(path, { method: "DELETE" });

// ---- Projects ----

export interface CreateProjectPayload {
  name: string;
  description?: string;
  default_backend: AgentBackend;
  default_model?: string;
  default_context_strategy?: string;
}

export const listProjects = (archived = false) =>
  get<ListResponse<Project>>(`/api/projects${archived ? "?archived=true" : ""}`);

export const createProject = (payload: CreateProjectPayload) =>
  post<Project>("/api/projects", payload);

export const getProject = (id: string) => get<Project>(`/api/projects/${id}`);

export const updateProject = (id: string, payload: Partial<CreateProjectPayload>) =>
  patch<Project>(`/api/projects/${id}`, payload);

export const archiveProject = (id: string) =>
  post<Project>(`/api/projects/${id}/archive`);

export const unarchiveProject = (id: string) =>
  post<Project>(`/api/projects/${id}/unarchive`);

// ---- Directories ----

export const listDirectories = (projectId: string) =>
  get<ListResponse<DirectoryBinding>>(`/api/projects/${projectId}/directories`);

export const createDirectory = (
  projectId: string,
  payload: { path: string; access_scope: AccessScope },
) => post<DirectoryBinding>(`/api/projects/${projectId}/directories`, payload);

export const deleteDirectory = (projectId: string, bindingId: string) =>
  del<void>(`/api/projects/${projectId}/directories/${bindingId}`);

