export const updateMcpServer = (
  projectId: string,
  bindingId: string,
  payload: Partial<{ name: string; config: McpServerConfig }>,
) => patch<McpBinding>(`/api/projects/${projectId}/mcp-servers/${bindingId}`, payload);

export const deleteMcpServer = (projectId: string, bindingId: string) =>
  del<void>(`/api/projects/${projectId}/mcp-servers/${bindingId}`);

