// ---- Tasks ----

export interface CreateTaskPayload {
  title: string;
  initial_prompt: string;
  backend?: AgentBackend;
  model?: string;
  context_strategy?: string;
  media?: unknown[];
}

export const listTasks = (projectId: string, status?: string) =>
  get<ListResponse<Task>>(
    `/api/projects/${projectId}/tasks${status ? `?status=${status}` : ""}`,
  );

export const createTask = (projectId: string, payload: CreateTaskPayload) =>
  post<Task>(`/api/projects/${projectId}/tasks`, payload);

export const getTask = (id: string) => get<Task>(`/api/tasks/${id}`);

export const cancelTask = (id: string) => post<Task>(`/api/tasks/${id}/cancel`);

export const restartTask = (id: string) => post<Task>(`/api/tasks/${id}/restart`);

export const retryTaskNow = (id: string) => post<Task>(`/api/tasks/${id}/retry-now`);

export const switchTaskModel = (id: string, model: string) =>
  patch<Task>(`/api/tasks/${id}/model`, { model });

export const switchTaskContextStrategy = (id: string, context_strategy: string) =>
  patch<Task>(`/api/tasks/${id}/context-strategy`, { context_strategy });

export const compressTaskContext = (id: string) =>
  post<ContextSnapshot>(`/api/tasks/${id}/compress-context`);

// ---- Messages ----

export const listMessages = (taskId: string) =>
  get<ListResponse<Message>>(`/api/tasks/${taskId}/messages`);

export const sendMessage = (
  taskId: string,
  payload: { content_text?: string; media?: unknown[] },
) => post<Message>(`/api/tasks/${taskId}/messages`, payload);

export const getTranscript = async (taskId: string): Promise<string> => {
  const res = await fetch(`${BASE_URL}/api/tasks/${taskId}/transcript`, {
    method: "GET",
    headers: { Accept: "text/plain" },
  });
  if (!res.ok) {
    throw new ApiError(res.status, await res.text().catch(() => null));
  }
  return res.text();
};

// ---- Run attempts ----

export const listRunAttempts = (taskId: string) =>
  get<ListResponse<TaskRunAttempt>>(`/api/tasks/${taskId}/run-attempts`);

export { ApiError, BASE_URL };
